import Highlight, { defaultProps, Prism } from 'prism-react-renderer';
import React, { forwardRef } from 'react';
import styled from 'styled-components';

import Borders from '@dynatrace/strato-design-tokens/borders';
import Colors from '@dynatrace/strato-design-tokens/colors';
import Spacings from '@dynatrace/strato-design-tokens/spacings';
import Typography from '@dynatrace/strato-design-tokens/typography';

import { prismDqlLanguage } from './prism-dql-language.js';
import { DTPrismTheme } from './prism-theme.js';

export interface CodeHighlightProps {
  /**
   * Whether line numbers should be shown.
   * @defaultValue true
   */
  showLineNumbers?: boolean;
  language:
    | 'markup'
    | 'bash'
    | 'clike'
    | 'c'
    | 'cpp'
    | 'css'
    | 'javascript'
    | 'jsx'
    | 'coffeescript'
    | 'actionscript'
    | 'css-extr'
    | 'diff'
    | 'git'
    | 'go'
    | 'graphql'
    | 'handlebars'
    | 'json'
    | 'less'
    | 'makefile'
    | 'markdown'
    | 'objectivec'
    | 'ocaml'
    | 'python'
    | 'reason'
    | 'sass'
    | 'scss'
    | 'sql'
    | 'stylus'
    | 'tsx'
    | 'typescript'
    | 'wasm'
    | 'yaml';
  code: string;
  /**
   * Whether the content breaks into new lines automatically or not.
   * @defaultValue false
   */
  lineBreaks?: boolean;
  /** @defaultValue false */
  buttonPadding?: boolean;
  maxHeight?: number;
  size?: 'default' | 'condensed';
}

Prism.languages['dql'] = prismDqlLanguage;

// #region StyledComponents
const StyledLineNumberContainer = /* @__PURE__ */ styled.span<{
  $isCondensed: boolean;
}>(({ $isCondensed }) => {
  return {
    display: 'table-cell',
    position: 'sticky',
    left: '0',
    textAlign: 'right',
    paddingRight: Spacings.Size16,
    userSelect: 'none',
    color: Colors.Text.Neutral.Subdued,
    backgroundColor: Colors.Background.Container.Neutral.Subdued,
    borderRight: `${Borders.Width.Emphasized} ${Borders.Style.Default} ${Colors.Border.Neutral.Default}`,
  };
});

const StyledLineNumber = /* @__PURE__ */ styled.span<{
  $isCondensed: boolean;
}>(({ $isCondensed }) => {
  return {
    boxSizing: 'border-box',
    display: 'block',
    paddingLeft: $isCondensed ? Spacings.Size12 : Spacings.Size16,
    minWidth: $isCondensed ? '27px' : '33px',
    WebkitUserSelect: 'none',
    pointerEvents: 'none',
    userSelect: 'none',
    '::before': {
      content: 'attr(data-linenumber)',
    },
  };
});

const StyledLineContent = /* @__PURE__ */ styled.span<{
  $allowCopy?: boolean;
  $isSingleLine: boolean;
  $isCondensed: boolean;
}>(({ $allowCopy, $isSingleLine, $isCondensed }) => {
  return {
    display: 'table-cell',
    /* Allow the background color fill the entire container */
    width: '100%',
    paddingLeft: $isCondensed ? Spacings.Size12 : Spacings.Size16,
    paddingRight: $isCondensed ? Spacings.Size12 : Spacings.Size16,
    verticalAlign: $isSingleLine ? 'middle' : undefined,
  };
});

const StyledHighlightWrapper = /* @__PURE__ */ styled.pre<{
  $lineBreaks: boolean;
  $maxHeight?: number;
  $isCondensed?: boolean;
}>(({ $lineBreaks, $maxHeight, $isCondensed }) => {
  return {
    fontFamily: $isCondensed
      ? Typography.Code.Small.Default.Family
      : Typography.Code.Base.Default.Family,
    fontSize: $isCondensed
      ? Typography.Code.Small.Default.Size
      : Typography.Code.Base.Default.Size,
    fontWeight: Typography.Code.Base.Default.Weight,
    lineHeight: $isCondensed
      ? Typography.Code.Small.Default.LineHeight
      : Typography.Code.Base.Default.LineHeight,
    /* Default styling on Firefox has vertical margin. */
    margin: 0,
    padding: 0,

    overflow: 'visible',
    boxSizing: 'border-box',
    tabSize: 2,

    backgroundColor: Colors.Background.Surface.Default,

    flex: 1,

    /* Min-height to fit the copy-button */
    minHeight: `calc(2 * ${Spacings.Size6} + ${Spacings.Size32})`,
    whiteSpace: $lineBreaks ? 'pre-wrap' : 'pre',
    maxHeight: $maxHeight ? `${$maxHeight}px` : undefined,
  };
});

//FIXME: Figure out how reused selectors work in CSSObject mode.
const StyledLine = /* @__PURE__ */ styled.div<{
  $isSingleLine: boolean;
  $isCondensed: boolean;
}>(
  ({ $isCondensed }) => ({
    display: 'table-row',

    /*
     * This is to mock the line numbers column having the background color
     * reach the very top of the container (instead of putting a padding
     * on the <pre> tag.
     */
    '&:first-child': {
      [`${StyledLineNumber}, ${StyledLineContent}`]: {
        paddingTop: $isCondensed ? Spacings.Size6 : Spacings.Size12,
      },
    },

    '&:last-child': {
      [`${StyledLineNumber}, ${StyledLineContent}`]: {
        paddingBottom: $isCondensed ? Spacings.Size6 : Spacings.Size12,
      },
    },
  }),
  ({ $isSingleLine }) => {
    if (!$isSingleLine) {
      return;
    }

    return {
      height: `calc(2 * ${Spacings.Size6} + ${Spacings.Size32})`,
    };
  },
);

// #endregion

/** Highlights code with prism tokenisation */
export const CodeHighlight = /* @__PURE__ */ forwardRef<
  HTMLPreElement,
  CodeHighlightProps
>((props, forwardedRef) => {
  const {
    code,
    language,
    showLineNumbers = true,
    lineBreaks = false,
    buttonPadding: allowCopy = false,
    maxHeight,
    size = 'default',
  } = props;

  const isCondensed = size !== 'default';

  return (
    <StyledHighlightWrapper
      $lineBreaks={lineBreaks}
      $maxHeight={maxHeight}
      $isCondensed={isCondensed}
      ref={forwardedRef}
    >
      <Highlight
        {...defaultProps}
        language={language}
        code={code}
        theme={DTPrismTheme}
      >
        {({ tokens, getLineProps, getTokenProps }) => (
          <>
            {tokens.map((line, i) => {
              const isSingleLine = tokens.length === 1;
              return (
                <StyledLine
                  key={i}
                  $isSingleLine={isSingleLine}
                  $isCondensed={isCondensed}
                  {...getLineProps({ line, key: i })}
                >
                  {showLineNumbers ? (
                    <StyledLineNumberContainer
                      $isCondensed={isCondensed}
                      className="line-number"
                    >
                      <StyledLineNumber
                        $isCondensed={isCondensed}
                        data-linenumber={i + 1}
                      />
                    </StyledLineNumberContainer>
                  ) : null}
                  <StyledLineContent
                    $allowCopy={allowCopy}
                    $isSingleLine={isSingleLine}
                    $isCondensed={isCondensed}
                  >
                    {line.map((token, key) => (
                      <span key={key} {...getTokenProps({ token, key })} />
                    ))}
                  </StyledLineContent>
                </StyledLine>
              );
            })}
          </>
        )}
      </Highlight>
    </StyledHighlightWrapper>
  );
});
CodeHighlight['displayName'] = 'CodeHighlight';
